; hook.asm -- chapter 16: a hook on CHPUT
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "hook.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
band    EQU RAM_START       ; the colour of the band the border is in
; A routine of the program's own in H.CHPU, the hook CHPUT calls before every
; character: it changes the colour of the border, so that every character
; CHPUT prints is one band of the border. The page is printed again every
; frame, from the same point of the frame.
init:   di
        ld sp, SYS_AREA
        ld a, BLACK
        ld (FORCLR), a          ; ink
        ld a, WHITE
        ld (BAKCLR), a          ; paper
        ld a, LIGHT_GREEN
        ld (BDRCLR), a          ; border
        ld a, 1
        call CHGMOD
        ld hl, hook             ; H.CHPU: JP hook
        ld (H_CHPU + 1), hl
        ld a, $C3               ; JP
        ld (H_CHPU), a
frame:  ld a, BLACK
        ld (band), a            ; every frame the same bands
        ei
        halt                    ; the frame interrupt, and the BIOS's routine
h1:     call wait               ; down to the top of the picture
        ld hl, text
h2:     ld a, (hl)
        or a
        jr z, frame             ; the 0 at the end: the page again
        call CHPUT              ; and CHPUT calls H.CHPU
        inc hl
        jr h2

; hook: called by CHPUT through H.CHPU, before every character, with the
;       character in A. The border in the other colour. Keeps every register.
hook:   push af
        ld a, (band)
        xor BLACK ^ LIGHT_GREEN ; the other colour
        ld (band), a
        di                      ; the two bytes together (chapter 19)
        out (VDP_CTRL), a
        ld a, $87               ; register 7: the border
o1:     out (VDP_CTRL), a
        pop af
        ret

; wait: 700 turns of chapter 14's loop. Uses A, DE.
wait:   ld de, 700
wt:     dec de
        ld a, d
        or e
        jr nz, wt
        ret

text:   db 27, "Y", 32+11, 32+0, "H.CHPU SEES EVERY CHARACTER.", 0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
